mapper.select:
select a.request_id, a.requester_id, a.receiver_id, a.status, a.created_at, a.updated_at,
b.profile_id as sender_profile_id, b.nickname as sender_nickname, b.stored_name as sender_profile_image ,
c.profile_id as receiver_profile_id, c.nickname as receiver_nickname, c.stored_name as receiver_profile_image from friend_request_tbl a left join profile_tbl b on a.receiver_id = b.user_id left join profile_tbl c on a.requester_id = c.user_id where receiver_id = #{userId};
